public class CSVParser_iterator_TriageGen1Test {



    @Test
    public void testIterator_NextWithoutHasNext() throws IOException {
        String csv = "a,b\n1,2";
        try (CSVParser parser = CSVParser.parse(csv, CSVFormat.DEFAULT)) {
