public class CSVParser_iterator_TriageGen1Test {













    @Test(expected = IllegalStateException.class)
    public void testIterator_IOExceptionDuringNext() throws IOException {
        // Use a custom reader that throws IOException on read
        Reader throwingReader = new Reader() {
            @Override
            public int read(char[] cbuf, int off, int len) throws IOException {
                throw new IOException("Simulated IO Error");
            }

            @Override
            public void close() throws IOException {}
        };

        CSVParser parser = new CSVParser(throwingReader, CSVFormat.DEFAULT);
        Iterator<CSVRecord> iterator = parser.iterator();

        // Trigger getNextRecord() via hasNext() or next()
        iterator.hasNext();
    }
}
